<div class="flex flex-wrap items-center gap-4"><div class="inline-flex h-9 items-center justify-center rounded-lg bg-muted p-1"><button type="button" @click="view='calendar'" class="inline-flex items-center gap-2 rounded-md px-3 py-1 text-sm" :class="view==='calendar' && 'bg-background shadow-sm'"><x-capstone::icon name="Calendar" />Calendar</button><button type="button" @click="view='table'" class="inline-flex items-center gap-2 rounded-md px-3 py-1 text-sm" :class="view==='table' && 'bg-background shadow-sm'"><x-capstone::icon name="List" />Table</button></div><select class="h-9 rounded-md border px-3 text-sm bg-background" x-model="selectedPeriod" aria-label="Period"><option value="all">All Periods</option><template x-for="period in periods" :key="period.id"><option :value="period.id" x-text="period.name"></option></template></select></div>
